namespace my_project {

template <typename SelfT>
inline ibmw::co::Task<void> _ibmw_dds_rpc_client_loop_body_impl_rpc_client_module(SelfT* self) {
  try {
    MW_INFO("Start RPC loop.");

    uint32_t counter = 0;
    while (self->ctx_ptr_->Running()) {
      self->ctx_ptr_->LetMe();

      // --- Call GetFooData ---
      {
        ibmw::protocols::example::GetFooDataReq req;
        ibmw::protocols::example::GetFooDataRsp rsp;
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_GET_FOO_DATA_BEGIN
        req.msg("hello from template #" + std::to_string(counter));
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_GET_FOO_DATA_END

        auto status = co_await self->client_.GetFooData.Call(req, rsp);
        self->ctx_ptr_->LetMe();

        if (status.OK()) {
          (void)rsp;
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_GET_FOO_DATA_BEGIN
          MW_INFO("GetFooData OK: rsp.msg='{}', rsp.data.code={}, rsp.data.data='{}'",
                  rsp.msg(), rsp.data().code(), rsp.data().data());
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_GET_FOO_DATA_END
        }

        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_GET_FOO_DATA_BEGIN
        if (!status.OK()) {
          MW_WARN("GetFooData FAILED: {}", status.ToString());
        }
        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_GET_FOO_DATA_END
      }

      // --- Call GetBarData ---
      {
        ibmw::protocols::example::GetBarDataReq req;
        ibmw::protocols::example::GetBarDataRsp rsp;
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_GET_BAR_DATA_BEGIN
        req.msg("bar request #" + std::to_string(counter));
        ibmw::protocols::example::ExampleBar bar;
        bar.num(static_cast<int32_t>(counter));
        req.data(bar);
        // IBMW_RPC_CLIENT_REQUEST_PARAMETER_BUILD_GET_BAR_DATA_END

        auto status = co_await self->client_.GetBarData.Call(req, rsp);
        self->ctx_ptr_->LetMe();

        if (status.OK()) {
          (void)rsp;
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_GET_BAR_DATA_BEGIN
          MW_INFO("GetBarData OK: rsp.code={}, rsp.msg='{}'", rsp.code(), rsp.msg());
          // IBMW_RPC_CLIENT_RESPONSE_PARAMETER_CONSUME_GET_BAR_DATA_END
        }

        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_GET_BAR_DATA_BEGIN
        if (!status.OK()) {
          MW_WARN("GetBarData FAILED: {}", status.ToString());
        }
        // IBMW_RPC_CLIENT_RETURN_STATUS_HANDLING_GET_BAR_DATA_END
      }

      ++counter;

      // Wait 2 seconds before next round
      co_await ibmw::co::ScheduleAfter(
          ibmw::co::IbmwExecutor(self->time_executor_),
          std::chrono::seconds(2));
    }

    MW_INFO("Exit RPC loop.");
  } catch (const std::exception& e) {
    MW_ERROR("RpcLoop failed: {}", e.what());
  }

  co_return;
}

}  // namespace my_project
